cat > /tmp/gravity-ui-check/check.cjs <<'EOF'
const {chromium}=require('playwright');
const assert=require('node:assert/strict');
(async()=>{
  const browser=await chromium.launch({headless:true});
  const page=await browser.newPage({viewport:{width:1440,height:1000}});
  const errors=[];
  page.on('pageerror', error=>errors.push(error.message));
  await page.goto('http://localhost:5174');
  await page.screenshot({path:'/tmp/gravity-desktop.png',fullPage:true});
  await page.getByRole('button',{name:'Войти',exact:true}).click();
  assert(await page.getByText('Введите email',{exact:true}).isVisible());
  assert(await page.getByText('Введите пароль',{exact:true}).isVisible());
  await page.getByLabel('Email',{exact:true}).fill('incorrect');
  await page.getByRole('button',{name:'Войти',exact:true}).click();
  assert(await page.getByText('Введите корректный email').isVisible());
  await page.getByLabel('Email',{exact:true}).fill('test@example.com');
  await page.getByLabel('Пароль',{exact:true}).fill('test-password');
  await page.getByRole('checkbox',{name:'Запомнить меня'}).check();
  assert(await page.getByRole('checkbox',{name:'Запомнить меня'}).isChecked());
  const reveal=page.locator('.g-password-input button').first();
  await reveal.click();
  assert.equal(await page.locator('#password').getAttribute('type'),'text');
  await reveal.click();
  assert.equal(await page.locator('#password').getAttribute('type'),'password');
  await page.locator('#password').press('Enter');
  assert(await page.getByText('Вход пока недоступен',{exact:true}).isVisible());
  await page.setViewportSize({width:375,height:812});
  await page.reload();
  assert(await page.getByRole('button',{name:'Войти',exact:true}).isVisible());
  assert(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth));
  await page.screenshot({path:'/tmp/gravity-mobile.png',fullPage:true});
  assert.deepEqual(errors,[]);
  console.log('PASS: empty fields, email validation, remember checkbox, password reveal, Enter submission, unavailable-service message, mobile layout, no browser errors.');
  await browser.close();
})().catch(error=>{console.error(error);process.exit(1)});
EOF"
